    private RenderFragment RenderSecurity() => __builder =>
    {
        <section class="settings-section">
            <h3 class="section-title">Security</h3>
            <p class="section-subtitle">Manage your account security settings.</p>

            <!-- Change Password Panel -->
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                    <span>🔑 Change Password</span>
                    <span class="expand-icon">@(_changePasswordExpanded ? "▲" : "▼")</span>
                </button>
                @if (_changePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        @if (_securitySettings?.LastPasswordChange is not null)
                        {
                            <small class="text-muted">
                                Last changed: @_securitySettings.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                            </small>
                        }
                        <div class="action-bar mt-3">
                            <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                        </div>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="toggle-row mt-4">
                <div>
                    <div class="toggle-label">Two-Factor Authentication</div>
                    <div class="toggle-desc">
                        Add an extra layer of security to your account.
                        <span class="status-badge @(_twoFactorEnabled ? "enabled" : "disabled")">
                            @(_twoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </div>
                </div>
                <label class="switch">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="slider"></span>
                </label>
            </div>

            <!-- Active Sessions -->
            <h5 class="mt-4 mb-3">Active Sessions</h5>
            @if (_securitySettings?.Sessions is { Count: > 0 })
            {
                <div class="table-responsive">
                    <table class="table table-hover sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                var isCurrentSession = session == _securitySettings.Sessions[0];
                                <tr>
                                    <td>
                                        @session.Device
                                        @if (isCurrentSession)
                                        {
                                            <span class="badge bg-primary ms-2">Current</span>
                                        }
                                    </td>
                                    <td>@session.Location</td>
                                    <td>@FormatTimeAgo(session.LastActive)</td>
                                    <td>
                                        @if (!isCurrentSession)
                                        {
                                            <button class="btn btn-sm btn-outline-danger"
                                                    @onclick="() => RequestRevokeSession(session)">
                                                Revoke
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
        </section>
    };

    private RenderFragment RenderAppearance() => __builder =>
    {
        <section class="settings-section">
            <h3 class="section-title">Appearance</h3>
            <p class="section-subtitle">Customize how the application looks and feels.</p>

            <div class="form-group">
                <label class="form-label fw-semibold">Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        var t = theme;
                        <label class="radio-card @(_theme == t ? "selected" : "")">
                            <input type="radio" name="theme" value="@t"
                                   checked="@(_theme == t)"
                                   @onchange="() => _theme = t" />
                            <span class="radio-card-icon">@(t == "Light" ? "☀️" : t == "Dark" ? "🌙" : "💻")</span>
                            <span>@t</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label class="form-label fw-semibold">Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        var s = size;
                        <label class="radio-card @(_fontSize == s ? "selected" : "")">
                            <input type="radio" name="fontSize" value="@s"
                                   checked="@(_fontSize == s)"
                                   @onchange="() => _fontSize = s" />
                            <span class="radio-card-text" style="font-size: @(s == "Small" ? "0.8rem" : s == "Medium" ? "1rem" : "1.25rem")">Aa</span>
                            <span>@s</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label class="form-label fw-semibold">Language</label>
                <select class="form-select" @bind="_language">
                    @foreach (var lang in AvailableLanguages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="toggle-row">
                <div>
                    <div class="toggle-label">Compact Mode</div>
                    <div class="toggle-desc">Reduce spacing and padding for a denser layout</div>
                </div>
                <label class="switch">
                    <input type="checkbox" @bind="_compactMode" />
                    <span class="slider"></span>
                </label>
            </div>

            <!-- Live Preview -->
            <h5 class="mt-4 mb-3">Preview</h5>
            <div class="preview-area @(_theme.ToLower())-preview @(_compactMode ? "compact" : "")"
                 style="font-size: @(_fontSize == "Small" ? "0.85rem" : _fontSize == "Medium" ? "1rem" : "1.15rem")">
                <div class="preview-header">
                    <strong>Sample Card</strong>
                    <span class="preview-badge">@_theme Theme</span>
                </div>
                <p class="preview-text">
                    This is how your content will look with the current settings.
                    Font size is set to <strong>@_fontSize</strong>, compact mode is
                    <strong>@(_compactMode ? "on" : "off")</strong>, and language is <strong>@_language</strong>.
                </p>
                <div class="preview-actions">
                    <span class="preview-btn primary">Primary</span>
                    <span class="preview-btn secondary">Secondary</span>
                </div>
            </div>

            <div class="action-bar">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };
}

/* ===== Layout ===== */
.settings-layout {
    display: flex;
    min-height: calc(100vh - 80px);
    gap: 0;
}

/* ===== Sidebar ===== */
.settings-sidebar {
    width: 240px;
    min-width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    display: flex;
    flex-direction: column;
}

.sidebar-title {
    padding: 0 1.25rem 1rem;
    margin: 0;
    font-weight: 700;
    font-size: 1.1rem;
    color: #1a1a2e;
    border-bottom: 1px solid #e0e0e0;
}

.sidebar-link {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    border: none;
    background: none;
    color: #555;
    font-size: 0.95rem;
    cursor: pointer;
    text-align: left;
    width: 100%;
    transition: all 0.15s;
}

.sidebar-link:hover {
    background: #e9ecef;
    color: #1a1a2e;
}

.sidebar-link.active {
    background: #e3eafc;
    color: #2563eb;
    font-weight: 600;
    border-left: 3px solid #2563eb;
}

.sidebar-icon {
    font-size: 1.1rem;
    width: 1.5rem;
    text-align: center;
}

/* ===== Content Area ===== */
.settings-content {
    flex: 1;
    padding: 2rem 2.5rem;
    max-width: 780px;
    position: relative;
}

.settings-section {
    animation: fadeIn 0.2s ease-in;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(6px); }
    to { opacity: 1; transform: translateY(0); }
}

.section-title {
    font-weight: 700;
    font-size: 1.5rem;
    margin-bottom: 0.25rem;
    color: #1a1a2e;
}

.section-subtitle {
    color: #6b7280;
    margin-bottom: 1.5rem;
}

/* ===== Toast ===== */
.settings-toast {
    position: sticky;
    top: 0;
    z-index: 100;
    padding: 0.75rem 1rem;
    border-radius: 0.5rem;
    margin-bottom: 1rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-weight: 500;
    animation: slideDown 0.25s ease-out;
}

@keyframes slideDown {
    from { opacity: 0; transform: translateY(-10px); }
    to { opacity: 1; transform: translateY(0); }
}

.settings-toast.success {
    background: #d1fae5;
    color: #065f46;
    border: 1px solid #6ee7b7;
}

.settings-toast.error {
    background: #fee2e2;
    color: #991b1b;
    border: 1px solid #fca5a5;
}

.settings-toast.info {
    background: #dbeafe;
    color: #1e40af;
    border: 1px solid #93c5fd;
}

.toast-close {
    background: none;
    border: none;
    font-size: 1.25rem;
    cursor: pointer;
    color: inherit;
    padding: 0 0.25rem;
}

/* ===== Form Elements ===== */
.form-group {
    margin-bottom: 1.25rem;
}

.form-label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 500;
    color: #374151;
    font-size: 0.9rem;
}

.form-control,
.form-select {
    border-radius: 0.5rem;
    border: 1px solid #d1d5db;
    padding: 0.5rem 0.75rem;
    font-size: 0.95rem;
    transition: border-color 0.15s;
}

.form-control:focus,
.form-select:focus {
    border-color: #2563eb;
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
}

/* ===== Avatar ===== */
.avatar-area {
    display: flex;
    align-items: center;
    gap: 1.5rem;
    margin-bottom: 1.5rem;
}

.avatar-preview {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    overflow: hidden;
    background: #e5e7eb;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    border: 3px solid #d1d5db;
}

.avatar-preview img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 2.5rem;
}

.avatar-url-display {
    flex: 1;
}

/* ===== Toggle Switch ===== */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0;
}

.toggle-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.toggle-label {
    font-weight: 600;
    color: #1f2937;
}

.toggle-desc {
    font-size: 0.85rem;
    color: #6b7280;
    margin-top: 0.15rem;
}

.switch {
    position: relative;
    display: inline-block;
    width: 48px;
    height: 26px;
    flex-shrink: 0;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background-color: #ccc;
    border-radius: 26px;
    transition: 0.25s;
}

.slider::before {
    content: "";
    position: absolute;
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background: white;
    border-radius: 50%;
    transition: 0.25s;
}

.switch input:checked + .slider {
    background-color: #2563eb;
}

.switch input:checked + .slider::before {
    transform: translateX(22px);
}

/* ===== Channel List ===== */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0;
    border: 1px solid #e5e7eb;
    border-radius: 0.5rem;
    overflow: hidden;
}

.channel-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.65rem 1rem;
    border-bottom: 1px solid #f0f0f0;
}

.channel-row:last-child {
    border-bottom: none;
}

.channel-check {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    cursor: pointer;
    margin: 0;
}

.channel-check input[type="checkbox"] {
    width: 1.1rem;
    height: 1.1rem;
    accent-color: #2563eb;
}

.channel-name {
    font-weight: 500;
    color: #374151;
}

/* ===== Expandable Panel ===== */
.expandable-panel {
    border: 1px solid #e5e7eb;
    border-radius: 0.5rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.85rem 1rem;
    background: #f9fafb;
    border: none;
    cursor: pointer;
    font-weight: 600;
    color: #374151;
    font-size: 0.95rem;
}

.panel-header:hover {
    background: #f3f4f6;
}

.expand-icon {
    font-size: 0.8rem;
    color: #9ca3af;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e5e7eb;
    animation: fadeIn 0.2s ease-in;
}

/* ===== Status Badge ===== */
.status-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 999px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-left: 0.5rem;
}

.status-badge.enabled {
    background: #d1fae5;
    color: #065f46;
}

.status-badge.disabled {
    background: #fee2e2;
    color: #991b1b;
}

/* ===== Sessions Table ===== */
.sessions-table {
    font-size: 0.9rem;
}

.sessions-table th {
    font-weight: 600;
    color: #6b7280;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    border-bottom: 2px solid #e5e7eb;
}

/* ===== Radio Card Group ===== */
.radio-group {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
}

.radio-card {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.35rem;
    padding: 0.85rem 1.25rem;
    border: 2px solid #e5e7eb;
    border-radius: 0.75rem;
    cursor: pointer;
    transition: all 0.15s;
    min-width: 90px;
    text-align: center;
    font-size: 0.9rem;
    color: #374151;
}

.radio-card:hover {
    border-color: #93c5fd;
    background: #f0f7ff;
}

.radio-card.selected {
    border-color: #2563eb;
    background: #eff6ff;
    color: #1d4ed8;
    font-weight: 600;
}

.radio-card input[type="radio"] {
    display: none;
}

.radio-card-icon {
    font-size: 1.5rem;
}

.radio-card-text {
    font-weight: 700;
    line-height: 1;
}

/* ===== Live Preview ===== */
.preview-area {
    border: 1px solid #e5e7eb;
    border-radius: 0.75rem;
    padding: 1.25rem;
    transition: all 0.3s ease;
}

.preview-area.light-preview {
    background: #ffffff;
    color: #1f2937;
}

.preview-area.dark-preview {
    background: #1f2937;
    color: #f3f4f6;
    border-color: #374151;
}

.preview-area.system-preview {
    background: linear-gradient(135deg, #ffffff 50%, #1f2937 50%);
    color: #1f2937;
}

.preview-area.compact {
    padding: 0.65rem 0.85rem;
    line-height: 1.3;
}

.preview-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.preview-badge {
    padding: 0.2rem 0.6rem;
    border-radius: 999px;
    font-size: 0.75rem;
    font-weight: 600;
    background: rgba(37, 99, 235, 0.1);
