{"file_text": "@page "/settings"
@using sv_67d754b171f14d6b8a0a196b040ae4db.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <!-- Sidebar Navigation -->
    <nav class="settings-sidebar">
        <h4 class="sidebar-title">Settings</h4>
        @foreach (var section in _sections)
        {
            <button class="sidebar-link @(section == _activeSection ? "active" : "")"
                    @onclick="() => SetActiveSection(section)">
                <span class="sidebar-icon">@GetSectionIcon(section)</span>
                @section
            </button>
        }
    </nav>

    <!-- Main Content -->
    <div class="settings-content">
        @if (_loading)
        {
            <div class="text-center py-5"><div class="spinner-border" role="status"></div></div>
        }
        else
        {
            <!-- Toast -->
            @if (_showToast)
            {
                <div class="settings-toast @(_toastType)">
                    @_toastMessage
                    <button class="toast-close" @onclick="() => _showToast = false">&times;</button>
                </div>
            }

            @switch (_activeSection)
            {
                case "Profile":
                    @RenderProfile()
                    break;
                case "Notifications":
                    @RenderNotifications()
                    break;
                case "Security":
                    @RenderSecurity()
                    break;
                case "Appearance":
                    @RenderAppearance()
                    break;
            }
        }
    </div>
</div>

<!-- Revoke Session Confirmation Dialog -->
@if (_showRevokeDialog)
{
    <div class="modal-backdrop" @onclick="() => _showRevokeDialog = false"></div>
    <div class="confirm-dialog">
        <h5>Revoke Session</h5>
        <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke?.Device</strong>?
           This will sign out that device immediately.</p>
        <div class="dialog-actions">
            <button class="btn btn-secondary" @onclick="() => _showRevokeDialog = false">Cancel</button>
            <button class="btn btn-danger" @onclick="ConfirmRevokeSession">Revoke</button>
        </div>
    </div>
}

@code {
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";
    private bool _loading = true;

    // Toast
    private bool _showToast;
    private string _toastMessage = "";
    private string _toastType = "success";

    // Profile state
    private UserProfile? _profile;
    private UserProfile? _savedProfile;
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileBio = "";
    private string _profileAvatarUrl = "";

    // Notification state
    private NotificationPrefs? _notifPrefs;
    private bool _emailNotif;
    private bool _pushNotif;
    private bool _weeklyDigest;
    private List<(string Channel, bool Muted)> _channels = [];

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private bool _showRevokeDialog;
    private ActiveSession? _sessionToRevoke;

    // Appearance state
    private AppearanceSettings? _appearanceSettings;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] AvailableLanguages =
        ["English", "Spanish", "French", "German", "Japanese", "Portuguese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData("Profile");
        _loading = false;
    }

    private async Task SetActiveSection(string section)
    {
        _activeSection = section;
        _loading = true;
        _showToast = false;
        await LoadSectionData(section);
        _loading = false;
    }

    private async Task LoadSectionData(string section)
    {
        switch (section)
        {
            case "Profile":
                _savedProfile = await SettingsService.GetProfileAsync();
                ApplyProfileFromSaved();
                break;
            case "Notifications":
                _notifPrefs = await SettingsService.GetNotificationPrefsAsync();
                _emailNotif = _notifPrefs.EmailNotifications;
                _pushNotif = _notifPrefs.PushNotifications;
                _weeklyDigest = _notifPrefs.WeeklyDigest;
                _channels = _notifPrefs.MutedChannels.Select(c => (c, true)).ToList();
                break;
            case "Security":
                _securitySettings = await SettingsService.GetSecuritySettingsAsync();
                _twoFactorEnabled = _securitySettings.TwoFactorEnabled;
                _changePasswordExpanded = false;
                _currentPassword = _newPassword = _confirmPassword = "";
                break;
            case "Appearance":
                _appearanceSettings = await SettingsService.GetAppearanceAsync();
                _theme = _appearanceSettings.Theme;
                _fontSize = _appearanceSettings.FontSize;
                _language = _appearanceSettings.Language;
                _compactMode = _appearanceSettings.CompactMode;
                break;
        }
    }

    private void ApplyProfileFromSaved()
    {
        if (_savedProfile is null) return;
        _profileDisplayName = _savedProfile.DisplayName;
        _profileEmail = _savedProfile.Email;
        _profileBio = _savedProfile.Bio;
        _profileAvatarUrl = _savedProfile.AvatarUrl;
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        ApplyProfileFromSaved();
        ShowToast("Changes discarded.", "info");
    }

    private async Task SaveNotifications()
    {
        var mutedChannels = _channels.Where(c => c.Muted).Select(c => c.Channel).ToList();
        var prefs = new NotificationPrefs(_emailNotif, _pushNotif, _weeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    private void ToggleChannelMute(int index)
    {
        var ch = _channels[index];
        _channels[index] = (ch.Channel, !ch.Muted);
    }

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) ||
            string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            ShowToast("New passwords do not match.", "error");
            return;
        }

        if (_newPassword.Length < 8)
        {
            ShowToast("Password must be at least 8 characters.", "error");
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = _newPassword = _confirmPassword = "";
        _changePasswordExpanded = false;
        ShowToast("Password updated successfully!", "success");
    }

    private void RequestRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeDialog = true;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _showRevokeDialog = false;
        _sessionToRevoke = null;
        ShowToast("Session revoked.", "success");
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!", "success");
    }

    private void ShowToast(string message, string type)
    {
        _toastMessage = message;
        _toastType = type;
        _showToast = true;
    }

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    private string FormatTimeAgo(DateTime dt)
    {
        var span = DateTime.UtcNow - dt;
        if (span.TotalMinutes < 1) return "Just now";
        if (span.TotalMinutes < 60) return $"{(int)span.TotalMinutes}m ago";
        if (span.TotalHours < 24) return $"{(int)span.TotalHours}h ago";
        return $"{(int)span.TotalDays}d ago";
    }

    // -- Render fragments --

    private RenderFragment RenderProfile() => __builder =>
    {
        <section class="settings-section">
            <h3 class="section-title">Profile</h3>
            <p class="section-subtitle">Manage your public profile information.</p>

            <div class="avatar-area">
                <div class="avatar-preview">
                    @if (!string.IsNullOrWhiteSpace(_profileAvatarUrl))
                    {
                        <img src="@_profileAvatarUrl" alt="Avatar" />
                    }
                    else
                    {
                        <span class="avatar-placeholder">👤</span>
                    }
                </div>
                <div class="avatar-url-display">
                    <label class="form-label">Avatar URL</label>
                    <input type="url" class="form-control" @bind="_profileAvatarUrl" placeholder="https://example.com/avatar.png" />
                </div>
            </div>

            <div class="form-group">
                <label class="form-label">Display Name</label>
                <input type="text" class="form-control" @bind="_profileDisplayName" />
            </div>

            <div class="form-group">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" @bind="_profileEmail" />
            </div>

            <div class="form-group">
                <label class="form-label">Bio</label>
                <textarea class="form-control" rows="4" @bind="_profileBio"></textarea>
            </div>

            <div class="action-bar">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };

    private RenderFragment RenderNotifications() => __builder =>
    {
        <section class="settings-section">
            <h3 class="section-title">Notifications</h3>
            <p class="section-subtitle">Choose what notifications you receive.</p>

            <div class="toggle-group">
                <div class="toggle-row">
                    <div>
                        <div class="toggle-label">Email Notifications</div>
                        <div class="toggle-desc">Receive notifications via email</div>
                    </div>
                    <label class="switch">
                        <input type="checkbox" @bind="_emailNotif" />
                        <span class="slider"></span>
                    </label>
                </div>

                <div class="toggle-row">
                    <div>
                        <div class="toggle-label">Push Notifications</div>
                        <div class="toggle-desc">Receive push notifications in your browser</div>
                    </div>
                    <label class="switch">
                        <input type="checkbox" @bind="_pushNotif" />
                        <span class="slider"></span>
                    </label>
                </div>

                <div class="toggle-row">
                    <div>
                        <div class="toggle-label">Weekly Digest</div>
                        <div class="toggle-desc">Get a weekly summary of activity</div>
                    </div>
                    <label class="switch">
                        <input type="checkbox" @bind="_weeklyDigest" />
                        <span class="slider"></span>
                    </label>
                </div>
            </div>

            <h5 class="mt-4 mb-3">Muted Channels</h5>
            <div class="channel-list">
                @for (var i = 0; i < _channels.Count; i++)
                {
                    var idx = i;
                    <div class="channel-row">
                        <label class="channel-check">
                            <input type="checkbox" checked="@_channels[idx].Muted"
                                   @onchange="() => ToggleChannelMute(idx)" />
                            <span class="channel-name">#@_channels[idx].Channel</span>
                        </label>
                        <span class="badge @(_channels[idx].Muted ? "bg-secondary" : "bg-success")">
                            @(_channels[idx].Muted ? "Muted" : "Active")
                        </span>
                    </div>
                }
            </div>

            <div class="action-bar">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    };

    private RenderFragment RenderSecurity() => __builder =>
    {
        <section class="settings-section">
            <h3 class="section-title">Security</h3>
            <p class="section-subtitle">Manage your account security settings.</p>

            <!-- Change Password Panel -->
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                    <span>🔑 Change Password</span>
                    <span class="expand-icon">@(_changePasswordExpanded ? "▲" : "▼")</span>
                </button>
                @if (_changePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        @if (_securitySettings?.LastPasswordChange is not null)
                        {
                            <small class="text-muted">
                                Last changed: @_securitySettings.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                            </small>
                        }
                        <div class="action-bar mt-3">
                            <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                        </div>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="toggle-row mt-4">
                <div>
                    <div class="toggle-label">Two-Factor Authentication</div>
                    <div class="toggle-desc">
                        Add an extra layer of security to your account.
                        <span class="status-badge @(_twoFactorEnabled ? "enabled" : "disabled")">
                            @(_twoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </div>
                </div>
                <label class="switch">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="slider"></span>
                </label>
            </div>

            <!-- Active Sessions -->
            <h5 class="mt-4 mb-3">Active Sessions</h5>
            @if (_securitySettings?.Sessions is { Count: > 0 })
            {
                <div class="table-responsive">
                    <table class="table table-hover sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                var isCurrentSession = session == _securitySettings.Sessions[0];
                                <tr>
                                    <td>
                                        @session.Device
                                        @if (isCurrentSession)
                                        {
                                            <span class="badge bg-primary ms-2">Current</span>
                                        }
